6	const PACKAGE_VERSION = 1;
7	const MANIFEST_FILE = 'manifest.json';
8	const MANIFEST_KEYS = ['version', 'documents', 'checksum'];
9	const ENTRY_KEYS = ['id', 'title', 'tags', 'file', 'sha256'];
10	const HEX_SHA256 = /^[0-9a-f]{64}$/u;
