31	function compareCodePoints(a, b) {
32	  const left = Array.from(a, (char) => char.codePointAt(0));
33	  const right = Array.from(b, (char) => char.codePointAt(0));
34	  for (let i = 0; i < Math.min(left.length, right.length); i += 1) {
35	    if (left[i] !== right[i]) return left[i] - right[i];
