56	// ---- Pure package build/parse ---------------------------------------------
57	
58	// Builds the on-disk package for a validated version-1 snapshot (documents
59	// already normalized and code-point sorted, checksum matching).
60	export function buildPackage(snapshot) {
61	  const files = new Map();
62	  const entries = snapshot.documents.map((document) => {
63	    const name = `${document.id}.md`;
64	    files.set(name, encodeBody(document.body));
65	    return {
66	      id: document.id,
67	      title: document.title,
68	      tags: structuredClone(document.tags),
69	      file: name,
70	      sha256: sha256Bytes(files.get(name)),
71	    };
72	  });
73	  const manifest = { version: PACKAGE_VERSION, documents: entries, checksum: snapshot.checksum };
74	  const manifestText = `${JSON.stringify(manifest)}\n`;
75	  const manifestBytes = Buffer.from(manifestText, 'utf8');
76	  files.set(MANIFEST_FILE, manifestBytes);
77	  return { manifest, files, manifestText };
78	}
79	
80	// Parses a raw manifest object and verifies every declared document file's
81	// bytes. Returns normalized, code-point-sorted entries carrying verified
82	// bodies, plus the manifest's bound snapshot checksum. Pure: never touches
83	// the file system.
84	export function parsePackage(manifestRaw, fileBytes) {
85	  if (!manifestRaw || typeof manifestRaw !== 'object' || Array.isArray(manifestRaw)) {
86	    throw invalidMarkdown('manifest must be a JSON object');
87	  }
88	  if (!sameKeys(manifestRaw, MANIFEST_KEYS)) {
89	    throw invalidMarkdown('manifest must contain exactly version, documents, and checksum');
90	  }
91	  const { version, documents, checksum } = manifestRaw;
92	  if (typeof version !== 'number' || version !== PACKAGE_VERSION) {
93	    throw invalidMarkdown(`unsupported manifest version: ${String(version)}`);
94	  }
95	  if (!Array.isArray(documents)) throw invalidMarkdown('manifest documents must be an array');
96	  if (typeof checksum !== 'string' || !HEX_SHA256.test(checksum)) {
97	    throw invalidMarkdown('manifest checksum must be a lowercase hex SHA-256');
98	  }
99	
100	  const seenIds = new Set();
101	  const entries = [];
102	  documents.forEach((raw, index) => {
103	    const location = `documents[${index}]`;
104	    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
105	      throw invalidMarkdown(`${location} must be an object`);
106	    }
107	    if (!sameKeys(raw, ENTRY_KEYS)) {
108	      throw invalidMarkdown(`${location} must contain exactly id, title, tags, file, and sha256`);
109	    }
110	    const { id, title, tags, file, sha256 } = raw;
111	    if (typeof id !== 'string') throw invalidMarkdown(`${location}.id must be a string`);
112	    if (typeof title !== 'string') throw invalidMarkdown(`${location}.title must be a string`);
113	    if (typeof file !== 'string') throw invalidMarkdown(`${location}.file must be a string`);
114	    if (typeof sha256 !== 'string' || !HEX_SHA256.test(sha256)) {
115	      throw invalidMarkdown(`${location}.sha256 must be a lowercase hex SHA-256`);
116	    }
117	    if (!Array.isArray(tags) || tags.some((tag) => typeof tag !== 'string')) {
118	      throw invalidMarkdown(`${location}.tags must be an array of strings`);
119	    }
120	    if (seenIds.has(id)) throw invalidMarkdown(`duplicate document id: ${id}`);
121	    seenIds.add(id);
122	    if (file !== `${id}.md`) throw invalidMarkdown(`${location}.file must equal ${id}.md`);
123	
124	    const bytes = fileBytes.get(file);
125	    if (bytes === undefined) throw invalidMarkdown(`missing package file: ${file}`);
126	    if (sha256Bytes(bytes) !== sha256) {
127	      throw invalidMarkdown(`sha256 mismatch for ${file}`);
128	    }
129	    let body;
130	    try {
131	      body = fatalDecoder.decode(bytes);
132	    } catch {
133	      throw invalidMarkdown(`illegal UTF-8 in package file: ${file}`);
134	    }
135	    try {
136	      assertDocument({ id, title, body, tags });
137	    } catch (error) {
138	      throw invalidMarkdown(`${location}: ${error.message}`);
139	    }
140	    entries.push({ id, title: title.trim(), body, tags: normalizeTags(tags), file, sha256 });
141	  });
142	
143	  entries.sort((a, b) => compareCodePoints(a.id, b.id));
144	  const titles = new Set();
145	  for (const entry of entries) {
146	    if (titles.has(entry.title)) throw invalidMarkdown(`duplicate normalized title: ${entry.title}`);
147	    titles.add(entry.title);
148	  }
149	
150	  const expectedFiles = new Set([MANIFEST_FILE, ...entries.map((entry) => entry.file)]);
151	  for (const name of fileBytes.keys()) {
152	    if (!expectedFiles.has(name)) throw invalidMarkdown(`unexpected package file: ${name}`);
153	  }
154	  return { entries, checksum };
155	}
156	
157	// ---- Path helpers ----------------------------------------------------------
158	
159	// Resolves symlinks of every existing path component, appending a nonexistent
160	// tail lexically, so aliased paths compare by their real on-disk location.
161	function realLocation(target) {
162	  let current = path.resolve(target);
163	  const tail = [];
164	  for (;;) {
165	    try {
166	      const real = fs.realpathSync(current);
167	      return tail.length === 0 ? real : path.join(real, ...tail.reverse());
168	    } catch (error) {
169	      if (error.code !== 'ENOENT' && error.code !== 'ENOTDIR') {
170	        throw ioError(`cannot resolve ${target}: ${error.message}`);
171	      }
172	      tail.push(path.basename(current));
173	      const parent = path.dirname(current);
174	      if (parent === current) return current;
175	      current = parent;
176	    }
177	  }
178	}
179	
180	function isInside(candidate, directory) {
181	  const relative = path.relative(directory, candidate);
182	  return relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative));
183	}
184	
185	// ---- File-system orchestration --------------------------------------------
186	
187	function readSnapshotText(file) {
188	  try {
189	    return fs.readFileSync(file, 'utf8');
190	  } catch (error) {
191	    throw ioError(`cannot read snapshot file ${file}: ${error.message}`);
192	  }
193	}
194	
195	function stagingFile(file) {
196	  const directory = path.dirname(path.resolve(file));
197	  return path.join(directory, `.${path.basename(file)}.${process.pid}.tmp`);
198	}
199	
200	function atomicWrite(file, content) {
201	  const temp = stagingFile(file);
202	  try {
203	    fs.writeFileSync(temp, content, 'utf8');
204	    fs.renameSync(temp, file);
205	  } catch (error) {
206	    try {
207	      fs.rmSync(temp, { force: true });
208	    } catch {
209	      // best-effort staging cleanup
210	    }
211	    throw ioError(`cannot write snapshot file ${file}: ${error.message}`);
212	  }
213	}
214	
215	// Enforces the package directory's structural rules and returns its parsed
216	// contents. The directory itself must be a real directory (not a symlink);
217	// it may contain only regular files with legal names — no symlinks,
218	// subdirectories, devices, or other special entries.
219	function readPackageDirectory(directory) {
220	  let rootStats;
221	  try {
222	    rootStats = fs.lstatSync(directory);
223	  } catch (error) {
224	    throw ioError(`cannot read package directory ${directory}: ${error.message}`);
225	  }
226	  if (rootStats.isSymbolicLink()) throw invalidMarkdown('package directory must not be a symlink');
227	  if (!rootStats.isDirectory()) throw ioError(`package input is not a directory: ${directory}`);
228	
229	  let names;
230	  try {
231	    names = fs.readdirSync(directory);
232	  } catch (error) {
233	    throw ioError(`cannot read package directory ${directory}: ${error.message}`);
234	  }
235	  if (!names.includes(MANIFEST_FILE)) throw invalidMarkdown(`missing package file: ${MANIFEST_FILE}`);
236	
237	  const fileBytes = new Map();
238	  for (const name of names) {
239	    if (name === '' || name === '.' || name === '..' || name.includes('/') || name.includes('\\')) {
240	      throw invalidMarkdown(`illegal package file name: ${name}`);
241	    }
242	    const full = path.join(directory, name);
243	    let stats;
244	    try {
245	      stats = fs.lstatSync(full);
246	    } catch (error) {
247	      throw ioError(`cannot read package file ${name}: ${error.message}`);
248	    }
249	    if (stats.isSymbolicLink()) throw invalidMarkdown(`symlinks are not allowed in a package: ${name}`);
250	    if (stats.isDirectory()) throw invalidMarkdown(`subdirectories are not allowed in a package: ${name}`);
251	    if (!stats.isFile()) throw invalidMarkdown(`illegal package entry: ${name}`);
252	    try {
253	      fileBytes.set(name, fs.readFileSync(full));
254	    } catch (error) {
255	      throw ioError(`cannot read package file ${name}: ${error.message}`);
256	    }
257	  }
258	
259	  let manifestRaw;
260	  try {
261	    manifestRaw = JSON.parse(fileBytes.get(MANIFEST_FILE).toString('utf8'));
262	  } catch {
263	    throw invalidMarkdown('manifest is not valid JSON');
264	  }
265	  return parsePackage(manifestRaw, fileBytes);
266	}
267	
268	function removeQuiet(target) {
269	  try {
270	    fs.rmSync(target, { recursive: true, force: true });
271	  } catch {
272	    // best-effort cleanup
273	  }
274	}
275	
276	// Exports a version-1 JSON snapshot file into a Markdown package directory.
277	// The package is materialized in a sibling staging directory and swapped into
278	// place with a single rename; fixed staging/backup names let a retry after a
279	// killed export finish a complete package with no stale files left behind.
280	export function exportMarkdown(snapshotFile, outputDirectory) {
281	  const output = path.resolve(outputDirectory);
282	  const parent = path.dirname(output);
283	  let parentStats;
284	  try {
285	    // Follow symlinked ancestors: only the target leaf itself being a symlink
286	    // is rejected below.
287	    parentStats = fs.statSync(parent);
288	  } catch (error) {
289	    throw ioError(`cannot access output parent ${parent}: ${error.message}`);
290	  }
291	  if (!parentStats.isDirectory()) throw ioError(`output parent is not a directory: ${parent}`);
292	
293	  let outputStats;
294	  try {
295	    outputStats = fs.lstatSync(output);
296	  } catch (error) {
297	    if (error.code !== 'ENOENT') throw ioError(`cannot access output directory ${outputDirectory}: ${error.message}`);
298	  }
299	  if (outputStats?.isSymbolicLink()) {
300	    throw new SnapshotError('INVALID_OPTIONS', 'output directory must not be a symlink');
301	  }
302	
303	  // Path-option checks precede reading so an invalid layout is reported even
304	  // when the source itself would be unreadable.
305	  const sourceReal = realLocation(snapshotFile);
306	  if (isInside(sourceReal, realLocation(output))) {
307	    throw new SnapshotError('INVALID_OPTIONS', 'output directory must not contain the source snapshot');
308	  }
309	
310	  const snapshotText = readSnapshotText(snapshotFile);
311	
312	  // All content validation happens before anything on disk changes.
313	  const workspace = new Workspace();
314	  workspace.importJSON(snapshotText, { mode: 'replace' });
315	  const snapshot = workspace.exportJSON();
316	  const { files, manifestText } = buildPackage(snapshot);
317	
318	  const stage = `${output}.export.tmp`;
319	  const backup = `${output}.old.tmp`;
320	  // Clear leftovers from a previously killed attempt first.
321	  removeQuiet(stage);
322	  removeQuiet(backup);
323	  let stageReady = false;
324	  try {
325	    fs.mkdirSync(stage);
326	    for (const [name, bytes] of files) fs.writeFileSync(path.join(stage, name), bytes);
327	    stageReady = true;
328	
329	    const hadTarget = outputStats !== undefined;
330	    if (hadTarget) fs.renameSync(output, backup);
331	    try {
332	      fs.renameSync(stage, output);
333	    } catch (error) {
334	      if (hadTarget) {
335	        try {
336	          fs.renameSync(backup, output);
337	        } catch {
338	          // surface the original failure with whatever can be restored
339	        }
340	      }
341	      throw error;
342	    }
343	    if (hadTarget) removeQuiet(backup);
344	  } catch (error) {
345	    if (stageReady) removeQuiet(stage);
346	    if (error instanceof SnapshotError) throw error;
347	    throw ioError(`cannot write package directory ${outputDirectory}: ${error.message}`);
348	  }
349	
350	  return { manifest: JSON.parse(manifestText), manifestText };
351	}
352	
353	// Imports a Markdown package over a base snapshot and writes the projected
354	// version-1 snapshot. Every validation step runs before the output is
355	// touched, so failure leaves the base snapshot and any existing output
356	// untouched. Returns the result snapshot plus the exact bytes saved.
357	export function importMarkdown(baseFile, inputDirectory, outputFile, mode, dryRun = false) {
358	  const input = path.resolve(inputDirectory);
359	  let inputStats;
360	  try {
361	    inputStats = fs.lstatSync(input);
362	  } catch (error) {
363	    throw ioError(`cannot read package directory ${inputDirectory}: ${error.message}`);
364	  }
365	  if (inputStats.isSymbolicLink()) throw invalidMarkdown('package directory must not be a symlink');
366	
367	  // Layout options are validated before any file content is read.
368	  const inputReal = realLocation(input);
369	  const outputReal = realLocation(outputFile);
370	  if (isInside(outputReal, inputReal)) {
371	    throw new SnapshotError('INVALID_OPTIONS', 'output snapshot must not be inside the input package');
372	  }
373	
374	  const baseText = readSnapshotText(baseFile);
375	  const { entries, checksum } = readPackageDirectory(input);
376	
377	  const baseWorkspace = new Workspace();
378	  baseWorkspace.importJSON(baseText, { mode: 'replace' });
379	
380	  // Rebuild the incoming snapshot from normalized entries and verify the
381	  // manifest's bound checksum exactly as a version-1 snapshot would compute.
382	  const incomingDocuments = entries.map(({ file: _file, sha256: _sha256, ...document }) => structuredClone(document));
383	  const incomingWorkspace = new Workspace();
384	  try {
385	    incomingWorkspace.importJSON(
386	      { version: 1, documents: incomingDocuments, checksum },
387	      { mode: 'replace' },
388	    );
389	  } catch (error) {
390	    if (error instanceof SnapshotError && error.code === 'INVALID_SNAPSHOT') {
391	      throw invalidMarkdown(`package does not rebuild a matching snapshot: ${error.message}`);
392	    }
393	    throw error;
394	  }
395	  const incomingSnapshot = incomingWorkspace.exportJSON();
396	  if (incomingSnapshot.checksum !== checksum) {
397	    throw invalidMarkdown('manifest checksum does not match the rebuilt snapshot');
398	  }
399	
400	  // Existing merge conflict / ids rules apply unchanged; replace installs
401	  // the package wholesale.
402	  const result = baseWorkspace.importJSON(incomingSnapshot, { mode });
403	
404	  const rendered = `${JSON.stringify(result)}\n`;
405	  if (!dryRun) atomicWrite(path.resolve(outputFile), rendered);
406	  return { snapshot: result, rendered: dryRun ? null : rendered };
407	}
