test('export refuses a source inside the staging or backup location and changes nothing', () => {
  const variants = [
    (dir) => {
      // Leftover staging directory from a killed previous export.
      const stage = path.join(dir, 'pkg.export.tmp');
      fs.mkdirSync(stage);
      fs.writeFileSync(path.join(stage, 'partial.md'), 'partial');
      fs.writeFileSync(path.join(stage, 'snap.json'), fs.readFileSync(path.join(dir, 'snap.json')));
      return { source: path.join(stage, 'snap.json'), output: path.join(dir, 'pkg'), stage };
    },
    (dir) => {
      // Leftover backup directory.
      const backup = path.join(dir, 'pkg.old.tmp');
      fs.mkdirSync(backup);
      fs.writeFileSync(path.join(dir, 'snap.json'), fs.readFileSync(path.join(dir, 'snap.json')));
      fs.writeFileSync(path.join(backup, 'snap.json'), fs.readFileSync(path.join(dir, 'snap.json')));
      return { source: path.join(backup, 'snap.json'), output: path.join(dir, 'pkg'), backup };
    },
    (dir) => {
      // The scratch location itself is the snapshot file (exact equality).
      const stage = path.join(dir, 'pkg.export.tmp');
      fs.writeFileSync(stage, fs.readFileSync(path.join(dir, 'snap.json')));
      return { source: stage, output: path.join(dir, 'pkg'), stage };
    },
  ];
  for (let index = 0; index < variants.length; index += 1) {
    const cwd = tempDir();
    writeSnapshot(path.join(cwd, 'snap.json'), workspaceWith([{ id: 'a', title: 'A', body: 'b', tags: [] }]));
    // A pre-existing target with content that must survive the rejection.
    fs.mkdirSync(path.join(cwd, 'pkg'));
    fs.writeFileSync(path.join(cwd, 'pkg', 'untouched'), 'yes');

    const { source, output, stage, backup } = variants[index](cwd);
    const sourceBefore = fs.readFileSync(source);
    assert.throws(
      () => exportMarkdown(source, output),
      (error) => error.code === 'INVALID_OPTIONS',
      `variant ${index}`,
    );
    // The source snapshot is intact and nothing at the scratch locations moved.
    assert.deepEqual(fs.readFileSync(source), sourceBefore, `variant ${index}`);
    assert.equal(fs.readFileSync(path.join(cwd, 'pkg', 'untouched'), 'utf8'), 'yes', `variant ${index}`);
    assert.deepEqual(fs.readdirSync(path.join(cwd, 'pkg')), ['untouched'], `variant ${index}`);
    assert.ok(!fs.existsSync(path.join(cwd, 'pkg.old.tmp')) || backup !== undefined, `variant ${index}`);
    if (stage) {
      assert.ok(fs.existsSync(stage), `variant ${index}`);
      assert.ok(fs.existsSync(path.join(stage, ...(fs.statSync(stage).isDirectory() ? ['snap.json'] : []))), `variant ${index}`);
    }
    if (backup) {
      assert.ok(fs.existsSync(path.join(backup, 'snap.json')), `variant ${index}`);
    }
  }
});

