276	// Exports a version-1 JSON snapshot file into a Markdown package directory.
277	// The package is materialized in a sibling staging directory and swapped into
278	// place with a single rename; fixed staging/backup names let a retry after a
279	// killed export finish a complete package with no stale files left behind.
280	export function exportMarkdown(snapshotFile, outputDirectory) {
281	  const output = path.resolve(outputDirectory);
282	  const parent = path.dirname(output);
283	  let parentStats;
284	  try {
285	    // Follow symlinked ancestors: only the target leaf itself being a symlink
286	    // is rejected below.
287	    parentStats = fs.statSync(parent);
288	  } catch (error) {
289	    throw ioError(`cannot access output parent ${parent}: ${error.message}`);
290	  }
291	  if (!parentStats.isDirectory()) throw ioError(`output parent is not a directory: ${parent}`);
292	
293	  let outputStats;
294	  try {
295	    outputStats = fs.lstatSync(output);
296	  } catch (error) {
297	    if (error.code !== 'ENOENT') throw ioError(`cannot access output directory ${outputDirectory}: ${error.message}`);
298	  }
299	  if (outputStats?.isSymbolicLink()) {
300	    throw new SnapshotError('INVALID_OPTIONS', 'output directory must not be a symlink');
301	  }
302	
303	  // Fixed staging/backup names used below. They are computed before any check
304	  // so the source can be protected against all three locations the export
305	  // replaces or removes — not just the final output directory.
306	  const stage = `${output}.export.tmp`;
307	  const backup = `${output}.old.tmp`;
308	
309	  // Path-option checks precede reading so an invalid layout is reported even
310	  // when the source itself would be unreadable. The source snapshot is user
311	  // input: it must never be deleted, moved, or rewritten merely because it
312	  // sits at (or inside) the output directory or either scratch location this
313	  // export is about to clear or swap. All comparisons use real locations so
314	  // paths reached through symlinked parents alias correctly even when the
315	  // output leaf does not exist yet.
316	  const sourceReal = realLocation(snapshotFile);
317	  const protectedLocations = [realLocation(output), realLocation(stage), realLocation(backup)];
318	  if (protectedLocations.some((location) => isInside(sourceReal, location))) {
319	    throw new SnapshotError(
320	      'INVALID_OPTIONS',
321	      'source snapshot must not be the output directory or an export staging or backup location',
322	    );
323	  }
324	
325	  const snapshotText = readSnapshotText(snapshotFile);
326	
327	  // All content validation happens before anything on disk changes.
328	  const workspace = new Workspace();
329	  workspace.importJSON(snapshotText, { mode: 'replace' });
330	  const snapshot = workspace.exportJSON();
331	  const { files, manifestText } = buildPackage(snapshot);
